      "fonte_ids": ["N.T_ASSEMBLY", "LOCAL.ASSEMBLY"],
      "justificativa": "O atributo avaliado é duração; N.T_ASSEMBLY informa a duração da atividade e LOCAL.ASSEMBLY especifica quando ela se mantém ou pode ser substituída."
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": ["N.T_ASSEMBLY"],
      "justificativa": "N.T_ASSEMBLY registra a duração em dias corridos, correspondente à unidade dia_corrido proposta."
    },
    "valor": {
      "estado": "sustentado",
      "fonte_ids": ["N.T_ASSEMBLY", "LOCAL.ASSEMBLY", "CHANGE.D02"],
      "justificativa": "N.T_ASSEMBLY e LOCAL.ASSEMBLY estabelecem duração de 5 dias. CHANGE.D02 relata nova disponibilidade contratada do fornecedor e declara que as demais durações são mantidas, sem alteração técnica da montagem."
    },
    "condicoes": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02", "LOCAL.ASSEMBLY"],
      "justificativa": "LOCAL.ASSEMBLY determina que mudanças exclusivamente de entrega ou preço mantêm a duração e que somente alteração técnica explícita permite substituí-la. CHANGE.D02 informa uma nova disponibilidade de SUP_MOTOR, mantém as demais durações e declara não haver alteração técnica da montagem."
    },
    "escopo": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D02"],
      "justificativa": "CHANGE.D02 define o evento como prospectivo a partir de D0 e restrito ao universo sintético Alfa v1, compatível com o escopo de projeto e versão indicado para a proposta."
    }
  },
  "fontes_examinadas": ["CHANGE.D02", "LOCAL.ASSEMBLY", "N.T_ASSEMBLY"],
  "justificativa": "A proposta confirma a manutenção da duração local vigente de T_ASSEMBLY. As fontes originais estabelecem 5 dias corridos e a regra local preserva esse valor diante de mudanças de entrega sem alteração técnica explícita. O relato de D02 confirma essas condições; as fontes citadas pela proposta estão cobertas.",
